describe('File Upload - File Name and Size Display', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display file name and size after selecting a file', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/files/upload').as('uploadFile');

    // Click the file input button
    cy.get('[data-testid="file-input-button"]').click();

    // Select a file using the file upload dialog
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    // Wait for the upload API call
    cy.wait('@uploadFile');

    // Verify file name is displayed
    cy.get('[data-testid="file-name-display"]').should('be.visible');
    cy.get('[data-testid="file-name-display"]').should('contain', 'sample.pdf');

    // Verify file size is displayed
    cy.get('[data-testid="file-size-display"]').should('be.visible');
    cy.get('[data-testid="file-size-display"]').should('contain', '1. 1 MB');

    // Verify success message is shown
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File uploaded successfully');

    // Verify file details container is visible
    cy.get('[data-testid="file-details-container"]').should('be.visible');
  });

  it('should handle file selection with invalid or unsupported file types', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/files/upload').as('uploadFile');

    // Click the file input button
    cy.get('[data-testid="file-input-button"]').click();

    // Attempt to select an unsupported file type (e.g., .exe)
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/sample.exe', { force: true });

    // Wait for the upload API call
    cy.wait('@uploadFile');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Unsupported file type');

    // Verify file name and size are NOT displayed
    cy.get('[data-testid="file-name-display"]').should('not.exist');
    cy.get('[data-testid="file-size-display"]').should('not.exist');

    // Verify file details container is hidden
    cy.get('[data-testid="file-details-container"]').should('not.exist');

    // Verify error icon is visible
    cy.get('[data-testid="error-icon"]').should('be.visible');
  });
});
